let rawText = $('Gmail Trigger').first().json.text;

// 1. Quitar saltos de línea y espacios extra
let cleaned = rawText.replace(/\n/g, "").trim();

// 2. Quitar el link de Mandrill
cleaned = cleaned.replace(/\[https:\/\/mandrillapp\.com\/track\/open\.php\?u=\d+&id=[a-z0-9]+\]/, "");
cleaned = cleaned.replace(/\[.*\]$/, "");

// 3. Eliminar coma extra antes de la llave de cierre }
cleaned = cleaned.replace(/,(\s*})/, '$1');

// 4. También limpiar comas extra en otras posiciones si las hay
cleaned = cleaned.replace(/,(\s*,)/g, ','); // comas duplicadas
cleaned = cleaned.replace(/,(\s*])/g, '$1'); // coma antes de ]

console.log('Texto limpiado:', cleaned);

// 5. Convertir a objeto JSON PRIMERO (con las comillas en las keys)
try {
    let jsonObject = JSON.parse(cleaned);
    console.log('JSON parseado exitosamente:', jsonObject);

    // 6. Revisar y normalizar el campo "telefono"
    if (jsonObject.telefono) {
        let rawTel = String(jsonObject.telefono).trim();
        console.log('Tel original (raw):', rawTel);

        // DEBUG: imprime códigos de caracteres
        const codes = Array.from(rawTel).map(ch => ch.charCodeAt(0));
        console.log('Char codes del telefono:', codes);

        // Extraer sólo dígitos (eliminar +, espacios, guiones, NBSP, etc.)
        let digits = rawTel.replace(/\D/g, '');
        console.log('Solo dígitos:', digits);

        // Normalizar prefijos
        if (digits.startsWith('+54915')) {
            // Caso: 54915 -> 54911
            digits = '54911' + digits.slice(5);
            console.log('✓ Corregido 54915 -> 54911:', digits);
        } else if (digits.startsWith('915')) {
            // Caso: 915 sin country code -> 54911
            digits = '54911' + digits.slice(3);
            console.log('✓ Corregido 915 -> 54911:', digits);
        } else if (digits.startsWith('11')) {
            // Caso: 11 sin country code -> 54911
            digits = '54911' + digits.slice(2);
            console.log('✓ Agregado country code a 11:', digits);
        } else if (!digits.startsWith('549')) {
            // Caso: no tiene 549 al inicio -> agregar
            digits = '549' + digits;
            console.log('✓ Agregado 549 al inicio:', digits);
        }

        // Formatear con +
        jsonObject.telefono = '+' + digits;
        console.log('Telefono final normalizado:', jsonObject.telefono);
    }

    console.log('Objeto final con telefono normalizado:', jsonObject);
    return jsonObject;

} catch (error) {
    console.error('Error al parsear JSON:', error);
    console.error('Texto problemático:', cleaned);

    // Si falla, intentar con eval() como alternativa (menos seguro pero funcional)
    try {
        console.log('Intentando con eval...');
        let evalResult = eval('(' + cleaned + ')');

        // Normalizamos telefono también aquí
        if (evalResult.telefono) {
            let rawTel = String(evalResult.telefono).trim();
            let digits = rawTel.replace(/\D/g, '');

            if (digits.startsWith('54915')) {
                digits = '54911' + digits.slice(5);
            } else if (digits.startsWith('915')) {
                digits = '54911' + digits.slice(3);
            } else if (digits.startsWith('11')) {
                digits = '54911' + digits.slice(2);
            } else if (!digits.startsWith('549')) {
                digits = '549' + digits;
            }

            evalResult.telefono = '+' + digits;
            console.log('Telefono normalizado (eval):', evalResult.telefono);
        }

        return evalResult;

    } catch (evalError) {
        console.error('Error con eval también:', evalError);
        return null;
    }
}

